function floor(key, name, x, z, dimensions, rotationY = 0, role = "functional") {
  return api.place({
    assetId: api.asset(key), name,
    position: api.roomPoint(x, z, 0),
    dimensions, rotationY, role
  });
}
function raised(key, name, x, z, bottom, dimensions, rotationY = 0, role = "functional") {
  return api.place({
    assetId: api.asset(key), name,
    position: api.roomPoint(x, z, bottom),
    dimensions, rotationY, role
  });
}
function relative(key, name, anchor, dx, dz, dimensions, rotationY, relation, range, role = "functional") {
  const distance = Math.hypot(dx, dz);
  if (distance < range[0] || distance > range[1]) {
    throw new Error("Invalid relation: " + relation);
  }
  return floor(key, name, anchor.x + dx, anchor.z + dz, dimensions, rotationY, role);
}
function shellArt(name, wall, offset, bottom, dimensions) {
  const frame = api.wallFrame(wall, offset, bottom, 0.035);
  return api.place({
    assetId: api.asset("art"), name,
    position: frame.point,
    facing: { direction: frame.inward },
    dimensions, role: "decor"
  });
}
function light(name, x, z, drop, scale = 1) {
  const dims = [0.48 * scale, 0.65 * scale, 0.48 * scale];
  return api.place({
    assetId: api.asset("pendant"), name,
    position: api.ceilingPoint(x, z, dims[1], drop),
    dimensions: dims, role: "decor"
  });
}
function wallX(name, x1, x2, z) {
  return floor("wall", name, (x1 + x2) / 2, z, [x2 - x1, H, 0.14]);
