  family("tablet", "预约平板", "One slim dark appointment tablet on a small angled bronze countertop stand, muted abstract booking interface with no readable lettering.", [0.3, 0.3, 0.2], "functional");
  family("vase", "花艺", "One small hand-thrown ivory ceramic vase holding a few delicate magnolia branches, airy asymmetric arrangement.", [0.42, 0.64, 0.34], "decor");
  family("divider", "矮柜屏风", "One low smoked oak storage credenza with subtly fluted doors, finished back, solid pale stone top, suitable as an open-zone divider.", [2.1, 1.05, 0.42]);

  function floor(key, name, x, z, dimensions, rotationY) {
    return api.place({
      assetId: api.asset(key), name,
      position: api.roomPoint(x, z, 0),
      dimensions, rotationY: rotationY || 0,
      role: ["rug", "plant", "vase"].includes(key) ? "decor" : "functional"
    });
  }
  function support(key, name, parentId, dimensions, offset, role) {
    return api.attach({
      assetId: api.asset(key), name, parentId, kind: "supported",
      anchorY: "bottom", dimensions, offset: offset || [0, 0],
      role: role || "decor"
    });
  }
  function light(name, x, z, width, drop) {
    return api.place({
      assetId: api.asset("pendant"), name,
      position: api.ceilingPoint(x, z, 0.5, drop),
      dimensions: [width, 0.5, 0.5], role: "decor"
    });
  }
  function wall(name, x, z, width, rotationY) {
    return floor("partition", name, x, z, [width, 4, 0.14], rotationY);
  }

  // Reserve a continuous perimeter promenade and a central cross before construction.
  // Existing doors enter the unobstructed perimeter, then reach the central cross.
  const openings = api.room.openings || [];
  const openingList = Array.isArray(openings) ? openings : Object.values(openings);
  if (!openingList.some(o => o && (o.kind === "door" || o.type === "door"))) {
    const openingId = api.opening({
      id: "spa-main-entry", kind: "door", wall: "south",
      offset: 0, bottom: 0, width: 1.25, height: 2.6
    });
    api.place({
      assetId: api.asset("entry"), name: "美容SPA入口",
      roomOpeningId: openingId, dimensions: [1.25, 2.6, 0.14], role: "functional"
    });
  } else {
    // Bind the declared entrance family to an existing door without changing its location.
    const o = openingList.find(o => o && (o.kind === "door" || o.type === "door"));
    api.place({
      assetId: api.asset("entry"), name: "SPA入口门",
      roomOpeningId: o.id,
      dimensions: [o.width || 1.25, o.height || 2.6, 0.14],
      role: "functional"
    });
  }

  // Two genuinely private, ceiling-height treatment rooms.
  // Their front door gaps are 1.15 m; open leaves stand inside clear swing pockets.
  for (const zone of zones.treatment) {
    const left = zone.x[0], right = zone.x[1];
    const back = zone.z[0], front = zone.z[1];
    const doorX = zone.center;
    const gap = 1.15;
    wall(zone.name + "后墙", zone.center, back, right - left + 0.14, 0);
    wall(zone.name + "左墙", left, (back + front) / 2, front - back, Math.PI / 2);
    wall(zone.name + "右墙", right, (back + front) / 2, front - back, Math.PI / 2);
    const leftEnd = doorX - gap / 2;
    const rightStart = doorX + gap / 2;
    const frontWall = wall(zone.name + "门左墙", (left + leftEnd) / 2, front, leftEnd - left, 0);
    wall(zone.name + "门右墙", (rightStart + right) / 2, front, right - rightStart, 0);
    api.place({
      assetId: api.asset("lintel"), name: zone.name + "门楣",
      position: api.roomPoint(doorX, front, 2.35),
      dimensions: [gap, 1.65, 0.14], role: "functional"
    });
    floor("door", zone.name + "开启门扇", leftEnd + 0.035, front - 0.53,
      [1.06, 2.32, 0.055], Math.PI / 2);
  }

  // Open reception: a low cabinet supplies a semi-private work edge.
  const receptionX = -3.65;
  const receptionZ = 3.2;
  const counter = floor("reception", "SPA接待主台", receptionX, receptionZ, [2.65, 1.05, 0.75]);
  floor("chair", "预约工作椅", receptionX, receptionZ - 1.05, [0.62, 0.87, 0.63]);
  support("tablet", "预约登记终端", counter, [0.3, 0.3, 0.2], [-0.48, -0.12], "functional");
  support("vase", "接待花艺", counter, [0.42, 0.64, 0.34], [0.83, 0.04]);
  const credenza = floor("divider", "接待后方用品矮柜", -3.7, 1.3, [2.1, 1.05, 0.42]);
  support("tea", "欢迎茶托盘", credenza, [0.56, 0.19, 0.36], [-0.45, 0]);
  support("towels", "迎宾热毛巾", credenza, [0.43, 0.22, 0.32], [0.56, 0]);
  floor("plant", "接待边绿植", -5.5, 3.75, [0.65, 1.85, 0.65]);
  light("接待台柔光", receptionX, receptionZ, 0.95, 0.55);

  // Dominant public relationship: a complete lounge facing the central tea table.
  const loungeX = 3.5;
  floor("rug", "茶叙区地毯", loungeX, 2.85, [3.85, 0.018, 3.25]);
  floor("sofa", "茶叙主沙发", loungeX, 1.65, [2.8, 0.86, 0.95]);
  const teaTable = floor("table", "茶叙中心茶几", loungeX, 2.95, [1.65, 0.4, 0.85]);
  support("tea", "候客茶具", teaTable, [0.56, 0.19, 0.36], [-0.3, 0.02]);
  support("vase", "茶几花艺", teaTable, [0.25, 0.38, 0.22], [0.51, 0]);
  floor("armchair", "茶叙客椅", loungeX + 0.85, 4.18, [0.84, 0.85, 0.86], Math.PI);
  floor("plant", "休息区绿植", 5.55, 1.75, [0.65, 1.85, 0.65]);
  light("茶叙区主吊灯", loungeX, 2.95, 1.05, 0.7);

  // Treatment constellations use identical measured relations, leaving a clear door aisle.
  for (const zone of zones.treatment) {
    const x = zone.center;
    const bedX = x - 0.66;
    const bedZ = -2.75;
    floor("bed", zone.name + "护理床", bedX, bedZ, [0.9, 0.82, 2.05]);
    floor("stool", zone.name + "护理师座凳", bedX + 1.55, bedZ - 0.65,
      [0.48, 0.55, 0.48]);
    const trolley = floor("trolley", zone.name + "床侧护理推车",
      bedX - 1.12, bedZ + 0.15, [0.55, 0.79, 0.65]);
    support("towels", zone.name + "精油毛巾", trolley, [0.43, 0.22, 0.32]);
    const vanity = floor("vanity", zone.name + "洗手台",
      x + 1.58, -4.02, [1.1, 0.94, 0.56]);
    support("mirror", zone.name + "洗手台镜", vanity,
      [0.65, 0.85, 0.13], [0, -0.18]);
    floor("cabinet", zone.name + "毛巾储物柜",
      x + 1.86, -2.47, [0.95, 1.8, 0.48], -Math.PI / 2);
    light(zone.name + "床上漫射光", bedX, bedZ, 0.75, 0.65);
    light(zone.name + "洗手区柔光", x + 1.45, -3.7, 0.5, 0.4);
  }

  // The perimeter remains empty: >=1.3 m at east/west, 1.48 m behind
  // the treatment rooms, and >=1.3 m in front of the lounge.
  // Both room entrances connect directly to the 1.5 m central cross aisle.
}
